 m=re.search(rf'Demo pair \d+ {label} \(28x28\):\n(.*?)(?=\n(?:Demo pair|Same instance))',t,re.S)
 lines=m.group(1).splitlines()
 return [[int(x) for x in line.split()] for line in lines]

